def process_queries(Q: int, queries: List[Tuple[int, int]]) -> List[int]:
    A = []
    results = []

    for i in range(Q):
        if queries[i][0] == 1:
            A.append(queries[i][1])
        elif queries[i][0] == 2:
            results.append(A[-queries[i][1]])

    return results
